        item(T('Orla Bardot · Armação','Orla Bardot · Armação','Orla Bardot · Armação'),T('Paseo, gastronomía y embarques cerca; estar junto al agua no equivale a playa de baño.','Passeio, gastronomia e embarques próximos; estar à beira-mar não significa praia para banho.','Promenade, food and boarding points nearby; being on the waterfront does not mean a swimming beach.')),
        item(T('Humaitá · Ossos','Humaitá · Ossos','Humaitá · Ossos'),T('Encanto, historia y acceso hacia Azeda; confirma pendientes, escaleras y maletas.','Charme, história e acesso rumo à Azeda; confirme ladeiras, escadas e bagagem.','Charm, history and access towards Azeda; check slopes, steps and luggage logistics.'))
