        item(T('Tucuns · José Gonçalves · Caravelas','Tucuns · José Gonçalves · Caravelas','Tucuns · José Gonçalves · Caravelas'),T('Naturaleza y retiro; solo elegir con acceso, camino, abastecimiento y regreso claros.','Natureza e retiro; escolha apenas com acesso, caminho, abastecimento e retorno claros.','Nature and seclusion; choose only with clear access, roads, supplies and return transport.'))
