    hero:img.street,
    facts:A(fact(T('Desde Río','Saindo do Rio','From Rio'),T('Bus · transfer · auto','Ônibus · transfer · carro','Bus · transfer · car')),fact(T('Aeropuertos','Aeroportos','Airports'),T('GIG y SDU son logísticas distintas','GIG e SDU têm logísticas diferentes','GIG and SDU require different logistics')),fact(T('Clave','Chave','Key detail'),T('Dirección final + equipaje','Endereço final + bagagem','Final address + luggage'))),
    sections:A(
      section(T('Compara modalidades','Compare as modalidades','Compare travel modes'),T('La salida “desde Río” cambia si partes de un hotel, una terminal o un aeropuerto.','A saída “do Rio” muda se você parte de hotel, rodoviária ou aeroporto.','“From Rio” means different things when leaving a hotel, bus terminal or airport.'),A(
        item(T('Bus interurbano','Ônibus rodoviário','Intercity bus'),T('Consulta fecha, origen, equipaje y terminal en el canal oficial de la empresa. El mostrador 1001 de GIG no demuestra que todos los horarios salgan desde el aeropuerto.','Consulte data, origem, bagagem e terminal no canal oficial da empresa. O balcão da 1001 no GIG não prova que todos os horários saiam do aeroporto.','Check date, origin, luggage and terminal through the operator’s official channel. The 1001 desk at GIG does not mean every service departs from the airport.')),
        item(T('Rodoviária de Búzios','Rodoviária de Búzios','Búzios bus terminal'),T('La guía turística oficial ubica la terminal utilizada por Auto Viação 1001 en Estrada da Usina Velha, 444, Loteamento Triângulo de Búzios. Úsala como referencia, pero confirma terminal, horario y billete para tu fecha directamente con la empresa antes de salir.','O guia turístico oficial localiza o terminal utilizado pela Auto Viação 1001 na Estrada da Usina Velha, 444, Loteamento Triângulo de Búzios. Use como referência, mas confirme terminal, horário e passagem para a sua data diretamente com a empresa antes de sair.','The official destination guide lists the terminal used by Auto Viação 1001 at Estrada da Usina Velha, 444, Loteamento Triângulo de Búzios. Use it as a reference point, but confirm the terminal, timetable and ticket for your date directly with the operator before departure.')),
        item(T('Transfer privado','Transfer privativo','Private transfer'),T('Útil con vuelo, equipaje, niños o dirección alejada. Para cotizar se necesitan terminal, número de vuelo, fecha, pasajeros, maletas y alojamiento.','Útil com voo, bagagem, crianças ou endereço afastado. Para cotar são necessários terminal, número do voo, data, passageiros, malas e hospedagem.','Useful with a flight, luggage, children or an outlying address. A quote needs terminal, flight number, date, passengers, bags and accommodation.')),
        item(T('Auto alquilado','Carro alugado','Rental car'),T('Da libertad regional, pero exige revisar recogida, estacionamiento del alojamiento, tránsito y si realmente lo usarás durante la estadía.','Dá liberdade regional, mas exige conferir retirada, estacionamento da hospedagem, trânsito e se você realmente usará o carro durante a estadia.','Offers regional freedom, but check collection, accommodation parking, traffic and whether you will actually use it during your stay.'))
      )),
      section(T('Cada origen necesita una pregunta distinta','Cada origem pede uma pergunta diferente','Each origin needs a different question'),T('Evita comprar un tramo incompleto que termine lejos de tu alojamiento.','Evite comprar um trecho incompleto que termine longe da hospedagem.','Avoid buying an incomplete journey that ends far from your accommodation.'),A(
        item(T('GIG · Galeão','GIG · Galeão','GIG · Galeão'),T('Confirma terminal y punto de encuentro. Un retraso internacional cambia espera, salida y coordinación.','Confirme terminal e ponto de encontro. Um atraso internacional muda espera, saída e coordenação.','Confirm terminal and meeting point. An international delay changes waiting time, departure and coordination.')),
        item(T('SDU · Santos Dumont','SDU · Santos Dumont','SDU · Santos Dumont'),T('No asumas bus directo. Revisa conexión, punto de salida o transfer específico desde este aeropuerto.','Não presuma ônibus direto. Confira conexão, ponto de saída ou transfer específico deste aeroporto.','Do not assume a direct bus. Check connections, departure point or a specific transfer from this airport.')),
        item(T('Ciudad de Río','Cidade do Rio','Rio city'),T('Hotel, terminal Novo Rio y domicilio son orígenes diferentes; informa el lugar completo.','Hotel, Rodoviária Novo Rio e endereço residencial são origens diferentes; informe o local completo.','A hotel, Novo Rio bus terminal and a private address are different origins; provide the full location.')),
        item(T('Aeropuerto de Cabo Frio','Aeroporto de Cabo Frio','Cabo Frio airport'),T('Solo sirve si tu vuelo existe para esa fecha. Los anuncios de rutas antiguas no sustituyen el billete confirmado.','Só serve se o voo existir na sua data. Anúncios antigos de rotas não substituem a passagem confirmada.','Only relevant if your flight operates on that date. Old route announcements do not replace a confirmed ticket.'))
      ),'alt')
    ),
    notice:T('Antes de reservar, solicita proveedor, recorrido, vehículo, espera, equipaje, sillas infantiles si necesitas, valor total y política ante demoras. Envía la dirección de llegada para que la cotización responda a tu viaje.','Antes de reservar, peça fornecedor, percurso, veículo, espera, bagagem, cadeirinha se precisar, valor total e política para atrasos. Informe o endereço de chegada para receber uma cotação adequada.','Before booking, request provider, route, vehicle, waiting arrangements, luggage, child seats if needed, total price and delay policy. Send the arrival address so the quote fits your journey.'),
    whatsapp:T('Hola Ernestinho, quiero consultar cómo llegar a Búzios. Origen: __. Fecha: __. Vuelo/terminal: __. Pasajeros: __. Equipaje: __. Alojamiento en Búzios: __.','Olá Ernestinho, quero consultar como chegar a Búzios. Origem: __. Data: __. Voo/terminal: __. Passageiros: __. Bagagem: __. Hospedagem em Búzios: __.','Hi Ernestinho, I would like help getting to Búzios. Origin: __. Date: __. Flight/terminal: __. Passengers: __. Luggage: __. Búzios accommodation: __.'),
    related:A(link(T('Moverse dentro de Búzios','Circular dentro de Búzios','Getting around Búzios'),'/destinos/buzios/moverse/',T('Resuelve el último tramo','Resolva o último trecho','Solve the final stretch')),link(T('Dónde alojarse','Onde ficar','Where to stay'),'/destinos/buzios/alojamiento/',T('La dirección cambia la llegada','O endereço muda a chegada','The address changes the arrival')),link(T('Transporte privado Río','Transporte privativo Rio','Rio private transport'),'/transportes/transporte-privado/',T('Servicio existente, cotización caso a caso','Serviço existente, cotação caso a caso','Existing service, quoted case by case')))
